export function createOpenPBRLUTs(device) {
	function makeStorageBuffer(data) {
		const buf = device.createBuffer({
			size: data.byteLength,
			usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST,
			mappedAtCreation: true,
		});
		new Float32Array(buf.getMappedRange()).set(data);
		buf.unmap();
		return buf;
	}

	return {
		lut2D: makeStorageBuffer(LUT_2D_DATA),
		lut3D_0: makeStorageBuffer(LUT_3D_0_DATA),
		lut3D_1: makeStorageBuffer(LUT_3D_1_DATA),
	};
}
